def to_underscore(string):
    if isinstance(string, int):
        return str(string)

    result = []
    for char in string:
        if char.isupper():
            if result and result[-1] != '_':
                result.append('_')
            result.append(char.lower())
        else:
            result.append(char)
    return ''.join(result)
